  H+='      <div>Address: '+ba+'</div>';
  H+='      <div>GSTIN/UIN &nbsp;: '+(bg||'&mdash;')+'</div>';
  if(bp)H+='<div>PAN &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: '+bp+'</div>';
  H+='      <div>State Name: '+(bst||'&mdash;')+(bsc?', Code: '+bsc:'')+'</div>';
  H+='    </div>';
  H+='  </div>';

  H+='  <div class="ih-right">';
