  H+='<table class="tax-table">';
  H+='  <thead>';
  H+='    <tr>';
  H+='      <th rowspan="2" style="width:110px">HSN/SAC</th>';
  H+='      <th rowspan="2" style="width:110px">Taxable<br/>Value</th>';
